fn layer(cx: i32, cy: i32, base: i32, amp: i32, k: i32, phase: i32, col: i32) {
    let mut px: i32 = 0;
    let mut py: i32 = 0;
    let mut a: i32 = 0;
    while a <= 256 {
        let r: i32 = base + (amp * host::math::sin(a * k + phase)) / 256;
        let x: i32 = cx + (r * host::math::cos(a)) / 256;
        let y: i32 = cy + (r * host::math::sin(a)) / 256;
        if a > 0 {
            host::display::draw_line(px, py, x, y, col);
        }
        px = x;
        py = y;
        a = a + 2;
    }
}

fn frame(t: i32) {
    host::display::clear(0x02000a);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2;
    layer(cx, cy, 130, 26, 6, t, 0x8844ff);
    layer(cx, cy, 90, 22, 9, 0 - t, 0xff66aa);
    layer(cx, cy, 55, 16, 12, t * 2, 0x66ffee);
    host::display::fill_rect(cx - 3, cy - 3, 6, 6, 0xffffff);
    host::display::present();
}
